{"implementation": "def solve(case):
    """Compute the mutual-reachability minimum spanning tree for an HDBSCAN-style graph."""
    payload = case.get("payload", case)
    nodes = list(payload.get("nodes", []))
    core = dict(payload.get("core_distance", {}))

    index = {node: i for i, node in enumerate(nodes)}
    edges = []
    for item in payload.get("distances", []):
        if len(item) != 3:
            continue
        a, b, d = item
        w = max(float(d), float(core[a]), float(core[b]))
        ia = index.get(a)
        ib = index.get(b)
        if ia is None or ib is None:
            continue
        left, right = (a, b) if ia <= ib else (b, a)
        edges.append((w, index[left], index[right], left, right))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
        return True

    tree = []
    for w, _, __, a, b in sorted(edges):
        if union(a, b):
            tree.append([a, b, w])
            if len(tree) == max(0, len(nodes) - 1):
                break

    return tree
